package uk.ac.ravensbourne.casevault.web;
import java.util.UUID; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.stereotype.Controller; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal; import uk.ac.ravensbourne.casevault.service.*; import uk.ac.ravensbourne.casevault.web.dto.CreateCaseRequest;
@Controller @RequestMapping("/cases") public class CaseController { private final CaseAccessService access; private final CaseManagementService management; private final ReportApprovalService reports; private final CaseWorkflowService workflow; public CaseController(CaseAccessService access,CaseManagementService management,ReportApprovalService reports,CaseWorkflowService workflow){this.access=access;this.management=management;this.reports=reports;this.workflow=workflow;} @GetMapping("/new") @PreAuthorize("hasRole('CLIENT_USER')") String createForm(){return "case-form";} @PostMapping @PreAuthorize("hasRole('CLIENT_USER')") String create(@AuthenticationPrincipal UserPrincipal p,@Valid @ModelAttribute CreateCaseRequest request,BindingResult errors){if(errors.hasErrors())return "case-form";return "redirect:/cases/"+management.create(p,request).getId();} @GetMapping String list(@AuthenticationPrincipal UserPrincipal p,@RequestParam(required=false) String q,@RequestParam(required=false) uk.ac.ravensbourne.casevault.domain.Category category,@RequestParam(required=false) uk.ac.ravensbourne.casevault.domain.Severity severity,@RequestParam(required=false) uk.ac.ravensbourne.casevault.domain.CaseStatus status,@RequestParam(required=false) UUID owner,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,@RequestParam(defaultValue="createdAt") String sort,org.springframework.ui.Model model){model.addAttribute("cases",workflow.search(p,q,category,severity,status,owner,page,size,sort));return "case-list";} @GetMapping("/{id}") @PreAuthorize("isAuthenticated()") @ResponseBody public String view(@AuthenticationPrincipal UserPrincipal principal,@PathVariable UUID id){return access.requireView(principal,id).getTitle();} @PostMapping("/{id}/assign") @PreAuthorize("hasRole('CASE_MANAGER')") String assign(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID id,@Valid @ModelAttribute uk.ac.ravensbourne.casevault.web.dto.CaseMutationRequests.Assign r){workflow.assign(p,id,r);return "redirect:/cases/"+id;} @PostMapping("/{id}/status") @PreAuthorize("hasRole('CASE_MANAGER')") String status(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID id,@Valid @ModelAttribute uk.ac.ravensbourne.casevault.web.dto.CaseMutationRequests.Status r){workflow.status(p,id,r);return "redirect:/cases/"+id;} @PostMapping("/{id}/notes") @PreAuthorize("hasAnyRole('SECURITY_ANALYST','CASE_MANAGER')") String note(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID id,@Valid @ModelAttribute uk.ac.ravensbourne.casevault.web.dto.CaseMutationRequests.Note r){workflow.note(p,id,r);return "redirect:/cases/"+id;} @PostMapping("/{id}/actions") @PreAuthorize("hasAnyRole('SECURITY_ANALYST','CASE_MANAGER')") String action(@AuthenticationPrincipal UserPrincipal p,@PathVariable UUID id,@Valid @ModelAttribute uk.ac.ravensbourne.casevault.web.dto.CaseMutationRequests.Action r){workflow.action(p,id,r);return "redirect:/cases/"+id;} @PostMapping("/{caseId}/reports/{reportId}/approve") @PreAuthorize("hasRole('CASE_MANAGER')") @ResponseBody public String approve(@AuthenticationPrincipal UserPrincipal principal,@PathVariable UUID caseId,@PathVariable UUID reportId){reports.approve(principal,caseId,reportId);return "approved";} }
